'use strict';
const taskStates=['Aguardando direção','Em criação','Em revisão','Entregue'];
let taskProject='all',taskStatus='all';
const taskById=id=>studio().tasks.find(t=>t.id===id);
const pendingTools=()=>studio().tasks.flatMap(t=>(t.requests||[]).filter(r=>r.status==='Pendente').map(r=>({...r,task:t.id,taskTitle:t.title})));
const durationLabel=n=>n%1440===0?`${n/1440} dia${n===1440?'':'s'}`:n%60===0?`${n/60} hora${n===60?'':'s'}`:`${n} min`;
function tasksValid(s){return Array.isArray(s.tasks)&&s.tasks.length<=1000&&new Set(s.tasks.map(t=>t?.id)).size===s.tasks.length&&s.tasks.every(t=>t&&['id','title','project','director','brief','format','status','result','plan','createdAt'].every(k=>typeof t[k]==='string'&&t[k].length<=10000)&&s.projects.some(p=>p.id===t.project)&&s.people.some(p=>p.id===t.director)&&taskStates.includes(t.status)&&Number.isInteger(t.minutes)&&t.minutes>0&&t.minutes<=525600&&!Number.isNaN(Date.parse(t.createdAt))&&Array.isArray(t.creators)&&t.creators.length<=3&&new Set(t.creators).size===t.creators.length&&t.creators.every(id=>id!==t.director&&s.people.some(p=>p.id===id))&&(t.status!=='Entregue'||t.result.trim().length>0&&evalsComplete(t))&&Array.isArray(t.requests)&&t.requests.length<=100&&t.requests.every(r=>r&&['id','tool','reason','cost','impact','by','status'].every(k=>typeof r[k]==='string'&&r[k].length<=10000)&&s.people.some(p=>p.id===r.by)&&['Pendente','Aprovada','Recusada'].includes(r.status))&&executionValid(t))}
function receptionPage(){const ts=studio().tasks,waiting=pendingTools();return `<section class="agency-intro"><div><span class="eyebrow">ESTÚDIO CRIATIVO · SUA AGÊNCIA DE IA</span><h1>Bem-vindo à <span>Jhoneme.</span></h1></div><span class="edition">DIREÇÃO HUMANA.<br>REPERTÓRIO COLETIVO.</span></section><section class="reception-hero"><img src="assets/studio.png" class="office-image" alt="Ambiente conceitual da Jhoneme: estúdio criativo com luz natural, mesa de trabalho e sala de reunião"><div class="hero-overlay"></div><div class="reception-copy"><span class="hero-kicker"><span></span>O espaço para a sua próxima ideia</span><h2>Você dá<br>a direção.<br><em>A criação ganha forma.</em></h2><p>Uma agência que se organiza em torno<br>dos seus projetos, do seu jeito e no seu tempo.</p><button class="btn orange" data-agency="new-task">Trazer um briefing ${ico('arrow')}</button></div><span class="office-caption">JHONEME / VISÃO CONCEITUAL DO ESTÚDIO</span><a href="#room" class="hero-room-link"><span>VAMOS CONVERSAR?</span><strong>Sala de reunião ${ico('arrow')}</strong><small>Chame a equipe e dê o próximo direcionamento.</small></a></section><div class="studio-ticker"><span>ESTRATÉGIA</span><b>✳</b><span>CRIAÇÃO</span><b>✳</b><span>CONTEÚDO</span><b>✳</b><span>RESULTADO</span><b>✳</b><span>SEU PRÓXIMO PROJETO</span></div><div class="reception-columns"><section class="agency-desk"><div class="section-heading"><div><span class="eyebrow">NA SUA MESA</span><h2>A próxima entrega começa aqui.</h2></div><a class="text-link" href="#tasks">Ver pautas ${ico('arrow')}</a></div>${ts.length?`<div class="desk-task-list">${ts.slice(0,3).map(t=>`<button class="desk-task" data-agency="task" data-id="${esc(t.id)}"><span class="desk-task-icon">${ico('pen')}</span><span><strong>${esc(t.title)}</strong><small>${esc(project(t.project)?.name)} · ${esc(person(t.director)?.name)} na direção</small></span><span class="task-duration">${ico('clock')}${durationLabel(t.minutes)}</span>${ico('arrow')}</button>`).join('')}</div>`:`<div class="first-brief"><span class="brief-symbol">↗</span><div><h3>Qual é o desafio de hoje?</h3><p>Escolha o projeto, conte o objetivo e defina o prazo.<br>A diretora será responsável por montar e coordenar a equipe.</p><button class="text-link" data-agency="new-task">Criar minha primeira pauta ${ico('plus')}</button></div></div>`}<div class="desk-metrics"><a href="#projects"><strong>${activeProjects().length.toString().padStart(2,'0')}</strong><span>projetos na casa</span></a><a href="#tasks"><strong>${ts.filter(t=>t.status!=='Entregue').length.toString().padStart(2,'0')}</strong><span>pautas abertas</span></a><a href="#approvals"><strong>${waiting.length.toString().padStart(2,'0')}</strong><span>pedidos de ferramentas</span></a></div></section><section class="meet-director"><span class="eyebrow">DIREÇÃO CRIATIVA</span>${(()=>{const p=studio().people.find(p=>/diretora? de cria/i.test(p.role))||studio().people[0];return p?`<div class="director-line"><img src="${personImage(p)}" alt="${esc(p.name)}, perfil fictício"><div><h3>${esc(p.name)}</h3><p>${esc(p.personality)}</p><button class="text-link" data-studio="person" data-id="${esc(p.id)}">Conhecer o perfil ${ico('arrow')}</button></div></div>`:'<p>Crie o perfil da sua diretora.</p>'})()}<div class="director-promise"><span>01</span><p><strong>Você define objetivo e prazo.</strong>A diretora escolhe até três criadores do banco de agentes.</p></div><div class="director-promise"><span>02</span><p><strong>A equipe se organiza por entrega.</strong>Ferramentas adicionais passam pela sua autorização.</p></div><a class="btn" href="#team">Conhecer toda a equipe ${ico('arrow')}</a></section></div><div class="section-heading rooms-heading"><div><span class="eyebrow">POR DENTRO DA JHONEME</span><h2>Entre. A agência é sua.</h2></div><span class="small muted">Cada sala abre um jeito de trabalhar.</span></div><section class="agency-rooms"><a class="agency-room room-creative" href="#tasks"><span class="room-number">01 / PRODUÇÃO</span><div class="room-drawing"><span class="paper one">IDEIA<br><b>↗</b></span><span class="paper two">BRIEFING<br><i></i><i></i><i></i></span><span class="paper three">✳</span></div><div class="agency-room-label"><div><h3>Sala de criação</h3><p>Do objetivo à entrega, com direção.</p></div>${ico('arrow')}</div></a><a class="agency-room room-conversation" href="#room"><span class="room-number">02 / ALINHAMENTO</span><div class="room-faces">${studio().people.slice(0,3).map(p=>`<img src="${personImage(p)}" alt="">`).join('')}<span>+</span></div><div class="agency-room-label"><div><h3>Sala de reunião</h3><p>Entreviste. Oriente. Dê o próximo passo.</p></div>${ico('arrow')}</div></a><a class="agency-room room-brands" href="#projects"><span class="room-number">03 / PORTFÓLIO</span><div class="brand-folders">${activeProjects().slice(0,3).map((p,i)=>`<span style="--folder-i:${i}">${esc(p.name)}</span>`).join('')||'<span>Sua próxima marca</span>'}</div><div class="agency-room-label"><div><h3>Projetos & marcas</h3><p>Os projetos mudam. A agência acompanha.</p></div>${ico('arrow')}</div></a></section><div class="prototype-note">${ico('help')}Ambiente navegável com registros locais. A coordenação e a produção automática dos agentes ainda precisam ser conectadas.</div>`}
function tasksPage(){const list=studio().tasks.filter(t=>(taskProject==='all'||t.project===taskProject)&&(taskStatus==='all'||t.status===taskStatus));return `${heading('A criação tem endereço.','Seu objetivo, seu prazo. Uma diretora responsável por fazer a entrega acontecer.',`<button class="btn primary" data-agency="new-task">${ico('plus')}Novo briefing</button>`)}<div class="workflow-ribbon"><span><b>01</b>Você define o desafio</span>${ico('arrow')}<span><b>02</b>A diretora escala até 3 criadores</span>${ico('arrow')}<span><b>03</b>Você autoriza ferramentas</span>${ico('arrow')}<span><b>04</b>Diretora revisa e entrega</span></div><div class="task-toolbar">${projectsSelect('task-project',taskProject)}<select id="task-status" class="btn" aria-label="Filtrar status"><option value="all">Todas as etapas</option>${taskStates.map(s=>`<option ${s===taskStatus?'selected':''}>${s}</option>`).join('')}</select><span class="small muted">${list.length} pauta${list.length===1?'':'s'} · acompanhamento manual</span></div>${list.length?`<div class="task-grid">${list.map(t=>`<article class="task-card"><div class="card-top"><span class="project-stamp">${esc(project(t.project)?.name)}</span>${chip(t.status)}</div><button class="task-title" data-agency="task" data-id="${esc(t.id)}"><h2>${esc(t.title)}</h2></button><p>${esc(t.brief)}</p><div class="task-deadline">${ico('clock')}<strong>${durationLabel(t.minutes)}</strong><span>tempo definido por você</span></div><div class="task-team"><img src="${personImage(person(t.director))}" alt="${esc(person(t.director)?.name)}"><span><strong>${esc(person(t.director)?.name)}</strong><small>${t.creators.length?`${t.creators.length} criador(es) no plano`:'Direção · equipe a definir'}</small></span><button class="icon-btn" data-agency="task" data-id="${esc(t.id)}" aria-label="Abrir pauta ${esc(t.title)}">${ico('arrow')}</button></div></article>`).join('')}</div>`:`<section class="empty-studio"><div class="empty-sketch">✳</div><span class="eyebrow">UMA FOLHA EM BRANCO. MUITAS POSSIBILIDADES.</span><h2>${studio().tasks.length?'Nenhuma pauta neste filtro.':'O que vamos criar primeiro?'}</h2><p>Uma pauta, um anúncio, um roteiro ou uma campanha.<br>Comece pelo resultado que você quer receber.</p><button class="btn primary" data-agency="new-task">Escrever o briefing ${ico('arrow')}</button></section>`}<div class="prototype-note">${ico('help')}O tempo é uma meta da tarefa. Salvar o briefing ainda não inicia agentes ou um cronômetro de produção.</div>`}
function taskForm(id){const old=taskById(id);if(!activeProjects().length&&!old){toast('Adicione um projeto antes de criar a pauta.');editProject();return}const t=old||{title:'',project:activeProjects()[0]?.id||'',director:studio().people.find(p=>p.id==='marina'&&p.status==='Aprovado')?.id||'',brief:'',format:'',minutes:'',status:taskStates[0],result:'',plan:'',creators:[],requests:[]};const directors=studio().people.filter(p=>p.status==='Aprovado'||p.id===t.director);if(!directors.length){toast('Primeiro aprove a contratação da diretora que coordenará o trabalho.');editPerson(studio().people.find(p=>p.id==='marina')?.id||studio().people[0]?.id);return}studioForm(old?'Editar briefing':'Qual é o desafio?','Sala de criação · Jhoneme',field('title','Nome da tarefa',t.title,'text','Ex.: Campanha de lançamento ou pauta da semana.',true)+selectField('project','Projeto ou marca',t.project,studio().projects.filter(p=>!p.archived||p.id===t.project).map(p=>[p.id,p.name]))+field('brief','Objetivo e contexto',t.brief,'textarea','O que deve acontecer depois que alguém consumir este material?',true)+field('format','Material que você quer receber',t.format,'textarea','Ex.: 3 anúncios com título, texto, CTA e orientação visual.',true)+selectField('director','Diretora responsável',t.director,[['','Escolha um perfil aprovado'],...directors.map(p=>[p.id,`${p.name} · ${p.role}`])])+`<div class="time-budget"><label class="field"><span>Quanto tempo você dá para esta tarefa?</span><input name="duration" type="number" min="1" max="525600" step="1" value="${t.minutes}" placeholder="Defina o tempo" required></label>${selectField('unit','Unidade','min',[['min','Minutos'],['hour','Horas'],['day','Dias']])}</div><div class="delegation-note">${ico('agents')}A diretora é responsável por selecionar até três criadores do banco de agentes, coordenar a revisão e pedir autorização se precisar de uma ferramenta.</div>`,fd=>{const minutes=Number(fd.get('duration'))*({min:1,hour:60,day:1440}[fd.get('unit')]||0);const patch=Object.fromEntries(['title','project','director','brief','format'].map(k=>[k,String(fd.get(k)||'').trim()]));if(!patch.title||!patch.brief||!patch.format||!patch.director)return {error:'Informe o objetivo, o material e a diretora responsável.'};if(!Number.isInteger(minutes)||minutes<1||minutes>525600)return {error:'Defina um tempo inteiro entre 1 minuto e 365 dias.'};if(t.creators.includes(patch.director))return {error:'Este perfil já está no plano como criador. Ajuste a equipe antes de torná-lo responsável.'};if(old&&old.execution?.startedAt&&minutes!==old.minutes)return {error:'A janela já foi iniciada. O tempo global não pode ser reiniciado pela edição do briefing.'};if(old){if(old.execution&&minutes!==old.minutes){old.execution.handoffs=[];old.execution.reviewMinutes=Math.max(1,Math.floor(minutes*.2))}if(old.execution&&patch.director!==old.director)old.execution.evals=old.execution.evals.filter(e=>e.agent!==old.director);Object.assign(old,{...patch,minutes});}else studio().tasks.unshift({...t,...patch,minutes,id:'task-'+crypto.randomUUID(),createdAt:new Date().toISOString()});return {action:`${old?'Ajustou':'Criou'} briefing: ${patch.title}`}})}
function taskDetail(id){const t=taskById(id);if(!t)return;const d=document.getElementById('editor');returnFocus=document.activeElement;editorDirty=false;d.className='drawer task-drawer';d.innerHTML=`<div class="drawer-header"><div><div class="eyebrow">${esc(project(t.project)?.name)} / SALA DE CRIAÇÃO</div><h2 id="editor-title">${esc(t.title)}</h2></div><button class="icon-btn" data-action="close" aria-label="Fechar">${ico('close')}</button></div><div class="drawer-body"><div class="task-detail-meta">${chip(t.status)}<span>${ico('clock')} ${durationLabel(t.minutes)} definidos por você</span></div><h3>O desafio</h3><p class="long-copy">${esc(t.brief)}</p><h3>Material esperado</h3><p class="long-copy">${esc(t.format)}</p><div class="lead-profile"><img src="${personImage(person(t.director))}" alt="Retrato de ${esc(person(t.director)?.name)}"><div><span class="eyebrow">DIREÇÃO RESPONSÁVEL</span><h3>${esc(person(t.director)?.name)}</h3><p>Coordena a equipe, revisa e responde pela entrega.</p></div></div><div class="section-heading"><h3>Plano da diretora</h3><button class="text-link" data-agency="task-plan" data-id="${esc(id)}">Registrar plano ${ico('pen')}</button></div><p class="long-copy">${esc(t.plan||'Aguardando definição da equipe e do plano. Nenhum agente foi acionado automaticamente.')}</p><div class="crew-row">${t.creators.map(id=>{const p=person(id);return `<span><img src="${personImage(p)}" alt=""><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></span>`}).join('')||'<span class="muted small">Até 3 criadores, escolhidos conforme a tarefa.</span>'}</div><div class="section-heading"><h3>Ferramentas necessárias</h3><button class="text-link" data-agency="tool-request" data-id="${esc(id)}">Registrar pedido ${ico('plus')}</button></div>${t.requests.length?t.requests.map(r=>`<div class="tool-inline"><strong>${esc(r.tool)}</strong><span class="chip">${esc(r.status)}</span><small>${esc(r.reason)}</small></div>`).join(''):'<p class="long-copy muted">Nenhum pedido registrado. Pedidos pendentes aparecem em Autorizações.</p>'}${qualitySection(t)}<div class="section-heading"><h3>Material entregue</h3><button class="text-link" data-agency="task-result" data-id="${esc(id)}">Registrar material ${ico('pen')}</button></div>${t.result?`<div class="result-copy">${esc(t.result)}</div><button class="btn" data-agency="download-result" data-id="${esc(id)}">${ico('download')}Baixar material</button>`:'<p class="long-copy muted">A entrega aparecerá aqui quando for registrada.</p>'}<div class="prototype-note">Registros e planos manuais nesta versão. O motor que permite à diretora contratar, coordenar e produzir de forma autônoma ainda não está conectado.</div></div><div class="drawer-footer"><button class="btn" data-agency="edit-task" data-id="${esc(id)}">${ico('pen')}Editar briefing</button><button class="btn primary" data-agency="export-task" data-id="${esc(id)}">${ico('download')}Levar ao ChatGPT</button></div>`;if(!d.open)d.showModal()}
function taskPlan(id){const t=taskById(id);const pool=studio().people.filter(p=>p.id!==t.director&&(t.creators.includes(p.id)||(p.status!=='Em pausa'&&(!p.projects.length||p.projects.includes(t.project)))));studioForm('Plano da diretora',t.title,`<p class="form-context">Registre a decisão da diretora. O banco mostra perfis disponíveis para este projeto. A seleção automática depende da conexão com IA.</p><span class="field-label">Criadores escolhidos · máximo 3</span><div class="checklist">${pool.map(p=>`<label><input name="creator" type="checkbox" value="${esc(p.id)}" ${t.creators.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(p.role)}</label>`).join('')}</div>`+field('plan','Divisão do trabalho e revisão',t.plan,'textarea','Registre o que cada criador fará e como a diretora usará o tempo disponível.')+selectField('status','Etapa registrada',t.status,taskStates.filter(x=>x!=='Entregue'||t.result.trim()&&evalsComplete(t))),fd=>{const creators=fd.getAll('creator');if(creators.length>3)return {error:'A diretora pode escalar no máximo três criadores.'};if(t.execution?.startedAt&&JSON.stringify(creators)!==JSON.stringify(t.creators))return {error:'A janela já iniciou. Preserve os participantes deste registro para manter a avaliação e o prazo.'};if(t.execution){t.execution.handoffs=t.execution.handoffs.filter(h=>creators.includes(h.agent));t.execution.evals=t.execution.evals.filter(e=>e.agent===t.director||creators.includes(e.agent))}t.creators=creators;t.plan=String(fd.get('plan')||'').trim();t.status=String(fd.get('status'));return {action:'Registrou plano da diretora: '+t.title}})}
function taskResult(id){const t=taskById(id);studioForm('Registrar material',t.title,field('result','Conteúdo produzido',t.result,'textarea','Cole a entrega real recebida. Não marcamos produção automática.',true)+selectField('status','Etapa',t.status==='Entregue'?'Entregue':'Em revisão',['Em revisão','Entregue']),fd=>{const result=String(fd.get('result')||'').trim();if(!result)return {error:'Adicione o material para registrar a entrega.'};if(fd.get('status')==='Entregue'&&!evalsComplete(t))return {error:'Registre as avaliações da diretora e de todos os criadores antes de concluir a entrega. Você pode salvar o material em revisão.'};t.result=result;t.status=String(fd.get('status'));return {action:'Registrou material: '+t.title}})}
function toolRequest(id){const t=taskById(id);studioForm('Pedido de ferramenta',t.title,selectField('by','Quem precisa da ferramenta?',t.director,[t.director,...t.creators].map(id=>[id,person(id).name]))+field('tool','Ferramenta ou recurso','', 'text','',true)+field('reason','Para que será usada?','','textarea','Descreva a necessidade e o resultado esperado.',true)+field('cost','Custo e limite solicitados','','text','Ex.: R$ 20 nesta tarefa, gratuita ou custo a confirmar.',true)+field('impact','Impacto no prazo','','textarea','Como a espera ou o uso da ferramenta afeta a entrega?',true),fd=>{const r=Object.fromEntries(['by','tool','reason','cost','impact'].map(k=>[k,String(fd.get(k)||'').trim()]));if(Object.values(r).some(v=>!v))return {error:'Preencha a necessidade, o custo e o impacto no prazo.'};t.requests.push({...r,id:'req-'+crypto.randomUUID(),status:'Pendente'});return {action:'Registrou pedido de ferramenta: '+r.tool}})}
function approvalsPage(){const all=studio().tasks.flatMap(t=>t.requests.map(r=>({...r,task:t.id,taskTitle:t.title})));return `${heading('Ferramentas passam por você.','A diretora ou um criador registra o que precisa. Você decide se autoriza.')}<div class="approval-rule">${ico('lock')}Uma autorização vale apenas para o pedido descrito. Ela não instala ferramentas, não libera acesso a contas e não inicia cobranças nesta versão.</div>${all.length?`<section class="approval-grid">${all.map(r=>`<article class="approval-card"><div class="card-top"><span class="eyebrow">${esc(person(r.by)?.name)} SOLICITA</span>${chip(r.status)}</div><h2>${esc(r.tool)}</h2><p>${esc(r.reason)}</p><dl><dt>Tarefa</dt><dd>${esc(r.taskTitle)}</dd><dt>Custo / limite</dt><dd>${esc(r.cost)}</dd><dt>Impacto no prazo</dt><dd>${esc(r.impact)}</dd></dl>${r.status==='Pendente'?`<div class="actions"><button class="btn primary" data-agency="approve-tool" data-id="${esc(r.id)}" data-task="${esc(r.task)}">${ico('check')}Autorizar pedido</button><button class="btn" data-agency="deny-tool" data-id="${esc(r.id)}" data-task="${esc(r.task)}">Recusar</button></div>`:'<p class="small muted">Sua decisão ficou registrada neste navegador.</p>'}</article>`).join('')}</section>`:`<section class="empty-studio"><div class="empty-sketch">↗</div><h2>Nenhum pedido na sua mesa.</h2><p>Quando uma ferramenta for necessária, o pedido deve trazer<br>o motivo, o custo e o impacto no prazo.</p><a class="btn" href="#tasks">Ir para as pautas ${ico('arrow')}</a></section>`}`}
function taskExport(t){const p=project(t.project),lead=person(t.director);return ['# Jhoneme — briefing para execução',`Tarefa: ${t.title}`,`Projeto: ${p.name}`,`Tempo disponível definido pelo usuário: ${durationLabel(t.minutes)}`,`Diretora responsável: ${lead.name} — ${lead.role}`,`Objetivo: ${t.brief}`,`Material esperado: ${t.format}`,'## Contrato de trabalho da diretora','Você coordena esta tarefa. Escolha até três criadores do banco abaixo conforme as competências necessárias. Divida o trabalho, reserve tempo para revisão e devolva o material dentro do tempo disponível quando o ambiente permitir. Se o prazo ou o escopo for inviável, sinalize e proponha um recorte. Não prometa execução em segundo plano. Se precisar de ferramenta ou gasto adicional, solicite ao usuário com finalidade, custo, limite e impacto no prazo. Aguarde autorização e acesso efetivo. Não invente ferramenta executada, contratação real ou material concluído.',`## Perfil da diretora\nPersonalidade: ${lead.personality}\nHabilidades: ${lead.skills}\nInstruções: ${lead.instructions}\nAutonomia: ${lead.autonomy}\nRegra definida na contratação: ${lead.workPolicy||'Preservar compromissos já assumidos e sinalizar conflitos.'}\nCapacidade contratada: ${lead.capacity||1} tarefa(s) simultânea(s)`,`## Contexto da marca\n${p.description}\nPúblico: ${p.audience}\nTom: ${p.tone}\nOrientações: ${p.notes}`,'## Banco de agentes disponíveis',...studio().people.filter(x=>x.id!==lead.id&&x.status!=='Em pausa'&&(!x.projects.length||x.projects.includes(p.id))).map(x=>`### ${x.name} — ${x.role}\nHabilidades: ${x.skills}\nPersonalidade: ${x.personality}\nVoz: ${x.voice}\nInstruções: ${x.instructions}`),`## Plano registrado\n${t.plan||'A definir'}\nCriadores: ${t.creators.map(id=>person(id).name).join(', ')||'A diretora deve selecionar'}`,'## Pedidos e decisões de ferramentas',...t.requests.map(r=>`${r.tool}: ${r.status}. Motivo: ${r.reason}. Custo: ${r.cost}. Impacto: ${r.impact}. Autorização registrada não equivale a credenciais ou instalação.`),qualityExport(t),t.result?`## Material registrado\n${t.result}`:''].filter(Boolean).join('\n\n')}
function tasksSummary(){return '\n\n## Pautas e entregas\n\n'+studio().tasks.map(taskExport).join('\n\n---\n\n')}
document.addEventListener('change',e=>{if(e.target.id==='task-project'){taskProject=e.target.value||'all';render()}if(e.target.id==='task-status'){taskStatus=e.target.value;render()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-agency]');if(!b)return;const a=b.dataset.agency,id=b.dataset.id;if(a==='new-task')taskForm();if(a==='task')taskDetail(id);if(a==='edit-task')taskForm(id);if(a==='task-plan')taskPlan(id);if(a==='task-result')taskResult(id);if(a==='tool-request')toolRequest(id);if(a==='export-task'){download('jhoneme-briefing.md',taskExport(taskById(id)),'text/markdown;charset=utf-8');toast('Briefing preparado. Anexe à conversa para iniciar o trabalho.')}if(a==='download-result')download('jhoneme-material.md',taskById(id).result,'text/markdown;charset=utf-8');if(a==='approve-tool'||a==='deny-tool'){const r=taskById(b.dataset.task)?.requests.find(r=>r.id===id);if(r&&r.status==='Pendente'){r.status=a==='approve-tool'?'Aprovada':'Recusada';saveStudio(`Ferramenta ${r.status.toLowerCase()}: ${r.tool}`)}}});
